message.content:
{
  "fields": {
    "unit": {
      "value": "patient_regimen",
      "evidence": [
        "article:p56"
      ],
      "explanation": "The headline metric (84.6% accuracy) is calculated over 39 evaluable treatments across 27 patients. Each treatment instance is a unique unit of comparison."
    },
    "platform": {
      "value": "organoid",
      "evidence": [
        "article:p12",
        "article:p30"
      ],
      "explanation": "Patient-derived tumor organoids (PDTOs) cultured in low-viscosity matrix suspension."
    },
    "readout": {
      "value": "viability",
      "evidence": [
        "article:p30",
        "article:p101"
      ],
      "explanation": "Viability quantified by mean PDTO size. Single agents use Area Under the Curve (AUC); combinations use mean pan-matrix viability score."
    },
    "direction": {
      "value": "lower_sensitive",
      "evidence": [
        "article:p40",
        "article:p101"
      ],
      "explanation": "Lower viability scores indicate higher drug sensitivity (cell death). Predictions of 'sensitive' correspond to scores below specific cutoffs."
    },
    "threshold_rule": {
      "value": "fixed_numeric",
      "evidence": [
        "article:p40"
      ],
      "explanation": "Therapy-specific numeric cutoffs were defined based on clinical trial response rates (e.g., 0.25 for 5FU, 0.50 for FOLFOX)."
    },
    "threshold_timing": {
      "value": "independent_reference",
      "evidence": [
        "article:p16",
        "article:p40"
      ],
      "explanation": "Cutoffs were derived from a treatment-naive community cohort and published literature, then applied to independent validation cohorts (community palliative and FORECAST-1)."
    },
    "patient_mapping": {
      "value": "partial",
      "evidence": [
        "supp/Sheet1",
        "article:p45",
        "article:p54"
      ],
      "explanation": "Supplementary Table 1 provides PDTO IDs and viability scores. The text provides aggregate counts of correct/incorrect predictions for the cohorts but does not provide a row-by-row mapping of every specific treatment instance to its binary clinical truth (0/1) in a machine-readable table. Truth must be inferred from aggregate descriptions or missing for specific rows."
    },
    "regimen_match": {
      "value": "matched",
      "evidence": [
        "article:p30",
        "article:p40"
      ],
      "explanation": "PDTOs were tested with agents corresponding to the clinical regimens received (e.g., FOLFOX, TAS-102)."
    },
    "n_units": {
      "value": 39,
      "evidence": [
        "article:p56"
      ],
      "explanation": "Total evaluable treatments in the combined cohort used for the headline accuracy statistic."
    },
    "split": {
      "value": "independent_test",
      "evidence": [
        "article:p16",
        "article:p40",
        "article:p46"
      ],
      "explanation": "Model developed on naive cohort, validated on independent community palliative patients and prospective FORECAST-1 cohort."
    }
  },
  "headline": {
    "metric": "accuracy",
    "reported": 0.846,
    "reported_evidence": [
      "article:p56"
    ],
    "threshold": null,
    "op": ">=",
    "score_direction": "higher",
    "tolerance": 0.005,
    "records": [],
    "blocked_reason": "Missing row-level clinical truth labels. The source provides aggregate accuracy (24/29 correct in community cohort, 9/10 correct in FORECAST-1) and supplementary viability scores (supp/Sheet1), but does not provide a table linking each specific PDTO ID and regimen to its individual binary clinical outcome (Benefit=1/No Benefit=0). Without this explicit mapping, individual records cannot be constructed to verify the headline metric."
  },
  "notes": [
    "The headline accuracy of 84.6% applies to 39 evaluable treatments (29 from community cohort + 10 from FORECAST-1).",
    "Thresholds are regimen-specific: 0.25 for 5FU/TAS-102, 0.20 for Irinotecan/Oxaliplatin/Anti-EGFR, 0.10 for Regorafenib, 0.50 for FOLFOX/FOLFIRI (article:p40).",
    "Supplementary Table 1 (supp/Sheet1) contains viability scores (AUC or pan-matrix) for PDTO lines but lacks the corresponding binary clinical truth column required for record-level verification.",
    "Text describes aggregate outcomes: Community cohort had 24/29 concordant predictions (article:p45); FORECAST-1 had 9/10 concordant predictions (article:p54). Total 33/39 = 84.6%.",
    "To resolve, a supplemental table mapping each of the 39 treatment instances to 'Clinical Benefit' (Yes/No) is required."
  ]
}
